def roman_to_int(s):
    v = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    t = 0
    for i, c in enumerate(s):
        if i + 1 < len(s) and v[c] < v[s[i+1]]: t -= v[c]
        else: t += v[c]
    return t

def is_balanced(s):
    pairs = {')':'(',']':'[','}':'{'}
    st = []
    for c in s:
        if c in '([{': st.append(c)
        elif c in pairs:
            if not st or st.pop() != pairs[c]: return False
    return not st

def merge_intervals(iv):
    out = []
    for a, b in sorted(iv):
        if out and a <= out[-1][1]: out[-1][1] = max(out[-1][1], b)
        else: out.append([a, b])
    return out

def flatten(x):
    out = []
    for i in x:
        if isinstance(i, list): out.extend(flatten(i))
        else: out.append(i)
    return out

def rle_encode(s):
    out = []; i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]: j += 1
        out.append(s[i] + str(j - i)); i = j
    return ''.join(out)

import re
def rle_decode(s):
    return ''.join(c * int(n) for c, n in re.findall(r'(\D)(\d+)', s))

def common_prefix(strs):
    if not strs: return ''
    p = strs[0]
    for s in strs[1:]:
        while not s.startswith(p): p = p[:-1]
    return p

def is_anagram(a, b):
    f = lambda s: sorted(s.lower().replace(' ', ''))
    return f(a) == f(b)

def spiral_order(m):
    m = [r[:] for r in m]; out = []
    while m:
        out += m.pop(0)
        m = [list(r) for r in zip(*m)][::-1]
    return out

from math import gcd
def gcd_list(nums):
    g = 0
    for n in nums: g = gcd(g, n)
    return g

def prime_factors(n):
    out = []; d = 2
    while n >= 2 and d * d <= n:
        while n % d == 0:
            out.append(d); n //= d
        d += 1
    if n >= 2: out.append(n)
    return out

import re
def camel_to_snake(s):
    s = re.sub(r'(?<=[a-z0-9])(?=[A-Z])', '_', s)
    s = re.sub(r'(?<=[A-Z])(?=[A-Z][a-z])', '_', s)
    return s.lower()

