def chunk(lst, n):
    if n <= 0: raise ValueError(n)
    return [lst[i:i+n] for i in range(0, len(lst), n)]

def dedupe(lst):
    out = []
    for x in lst:
        if x not in out: out.append(x)
    return out

def max_subarray(nums):
    if not nums: return 0
    best = cur = nums[0]
    for x in nums[1:]:
        cur = max(x, cur + x); best = max(best, cur)
    return best

def eval_rpn(tokens):
    st = []
    for t in tokens:
        if t in '+-*/' and len(t) == 1:
            b, a = st.pop(), st.pop()
            st.append(a + b if t == '+' else a - b if t == '-' else a * b if t == '*' else int(a / b))
        else: st.append(int(t))
    return st[0]

def count_islands(grid):
    if not grid: return 0
    seen = set(); n = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1 and (i, j) not in seen:
                n += 1; st = [(i, j)]; seen.add((i, j))
                while st:
                    a, b = st.pop()
                    for da, db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x, y = a + da, b + db
                        if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == 1 and (x, y) not in seen:
                            seen.add((x, y)); st.append((x, y))
    return n

def is_palindrome(s):
    t = [c.lower() for c in s if c.isalnum()]
    return t == t[::-1]
